<?php
require_once __DIR__.'/bootstrap.php';require_admin();$pageTitle='Danh mục';$active='categories';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';
try{
 if($action==='delete'){$pdo->prepare("DELETE FROM danhmuc WHERE id=?")->execute([$id]);flash('success','Đã xóa danh mục.');}
 else{$name=trim((string)($_POST['ten_danh_muc']??''));$slug=trim((string)($_POST['slug']??''))?:slugify($name);$desc=trim((string)($_POST['mo_ta']??''));$status=(int)($_POST['trang_thai']??1);if($name==='')throw new RuntimeException('Tên danh mục là bắt buộc.');if($id)$pdo->prepare("UPDATE danhmuc SET ten_danh_muc=?,slug=?,mo_ta=?,trang_thai=? WHERE id=?")->execute([$name,$slug,$desc,$status,$id]);else $pdo->prepare("INSERT INTO danhmuc (ten_danh_muc,slug,mo_ta,trang_thai) VALUES (?,?,?,?)")->execute([$name,$slug,$desc,$status]);flash('success','Đã lưu danh mục.');}
}catch(Throwable $e){flash('error',$e instanceof PDOException?'Không thể lưu/xóa: slug có thể bị trùng hoặc danh mục đang được sản phẩm sử dụng.':$e->getMessage());}redirect('categories.php');
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM danhmuc WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=$pdo->query("SELECT d.*,COUNT(s.id) AS so_san_pham FROM danhmuc d LEFT JOIN sanpham s ON s.danh_muc_id=d.id GROUP BY d.id ORDER BY d.id DESC")->fetchAll();
require __DIR__.'/admin-header.php';?>
<div class="form-grid"><section class="panel"><h2><?=$edit?'Sửa danh mục':'Thêm danh mục'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field" style="margin-top:18px"><label>TÊN DANH MỤC *</label><input name="ten_danh_muc" required value="<?=e($edit['ten_danh_muc']??'')?>"></div><div class="field" style="margin-top:15px"><label>SLUG</label><input name="slug" value="<?=e($edit['slug']??'')?>" placeholder="Tự tạo nếu để trống"></div><div class="field" style="margin-top:15px"><label>MÔ TẢ</label><textarea name="mo_ta"><?=e($edit['mo_ta']??'')?></textarea></div><div class="field" style="margin-top:15px"><label>TRẠNG THÁI</label><select name="trang_thai"><option value="1" <?=((int)($edit['trang_thai']??1)===1)?'selected':''?>>Đang hoạt động</option><option value="0" <?=((int)($edit['trang_thai']??1)===0)?'selected':''?>>Ẩn</option></select></div><div class="form-actions"><button class="btn">Lưu danh mục</button><?php if($edit):?><a class="btn light" href="categories.php">Hủy sửa</a><?php endif;?></div></form></section>
<section class="panel"><h2>Gợi ý</h2><p class="muted">Slug dùng trong đường dẫn thân thiện, ví dụ <code>vay-dam</code>. Nên giữ slug ổn định khi sản phẩm đã được liên kết.</p></section></div>
<section class="panel"><div class="panel-head"><h2>Danh sách danh mục</h2><span class="muted"><?=count($rows)?> danh mục</span></div><div class="table-wrap"><table><thead><tr><th>Tên</th><th>Slug</th><th>Sản phẩm</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['ten_danh_muc'])?></td><td><?=e($r['slug'])?></td><td><?=$r['so_san_pham']?></td><td><span class="badge <?=((int)$r['trang_thai']===1)?'':'off'?>"><?=((int)$r['trang_thai']===1)?'Hoạt động':'Ẩn'?></span></td><td><div class="actions"><a class="btn small light" href="?edit=<?=$r['id']?>">Sửa</a><form class="inline" method="post" onsubmit="return confirm('Xóa danh mục này?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn small danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/admin-footer.php';?>
